/**
 * 右侧滑出的 AI 面板：解释「这段话/这个词在这里为什么这样用」。
 *
 * 和词典卡片分工明确 —— 词典回答「这个词是什么意思」，只看词本身；
 * 这一块回答「它在这一段里的意思」，请求会把上下文一起发给 AI。
 *
 * 面板平时收在屏幕外，0.3 秒滑进来，不占正文宽度；关掉之后正文回到原样。
 */
import { BookmarkPlus, Languages, LoaderCircle, Sparkles, Volume2, X } from "lucide-react";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import type { LanguageInsight } from "@leafia/shared";
import { fallbackInsight } from "../../data/demo";
import { api } from "../../lib/api";
import { cn } from "../../lib/cn";
import { speakEnglish } from "../../lib/speak";
import { useReaderActions, type ReaderSource } from "./useReaderActions";
import "./reader-insight-panel.css";

export interface ReaderInsightRequest {
  /** selection：整段选中文字；word：上下文里的一个词。 */
  kind: "selection" | "word";
  text: string;
  contextBefore: string;
  contextAfter: string;
}

export interface ReaderInsightPanelProps {
  request: ReaderInsightRequest | null;
  source: ReaderSource;
  onClose: () => void;
}

export function ReaderInsightPanel({
  request,
  source,
  onClose,
}: ReaderInsightPanelProps) {
  const [shown, setShown] = useState<ReaderInsightRequest | null>(request);
  const [loading, setLoading] = useState(false);
  const [insight, setInsight] = useState<LanguageInsight | null>(null);
  const { addToReview, saveKnowledgeCard, addToCorpus } = useReaderActions(source);

  // 关闭时留着上一次的内容滑出去，滑完再丢掉。
  useEffect(() => {
    if (request) setShown(request);
    else {
      const timer = window.setTimeout(() => setShown(null), 320);
      return () => window.clearTimeout(timer);
    }
  }, [request]);

  useEffect(() => {
    if (!request) return;
    let cancelled = false;
    setLoading(true);
    setInsight(null);
    void api
      .insight({
        noteId: `book-${source.bookId}`,
        pageId: source.bookId,
        selectedText: request.text.slice(0, 500),
        contextBefore: request.contextBefore,
        contextAfter: request.contextAfter,
        locale: "zh-CN",
      })
      .then((response) => response.insight)
      .catch(() => fallbackInsight(request.text))
      .then((next) => {
        if (!cancelled) setInsight(next);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [request, source.bookId]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onClose]);

  const open = request !== null;
  const excerpt = request
    ? contextExcerpt(request.contextBefore, request.text, request.contextAfter)
    : null;

  // 挂到 body：路由舞台带 transform + filter，会把面板困在自己的层叠上下文里，
  // 右上角的 MENU 控件就会盖住面板标题栏。portal 出来之后 620 才真正生效。
  return createPortal(
    <aside
      className={cn("reader-insight", open && "is-open")}
      aria-label="AI 解读"
      aria-hidden={!open}
    >
      <header>
        <span className="reader-insight__eyebrow">
          <Sparkles size={13} />
          AI 解读 · 语境
        </span>
        <button type="button" onClick={onClose} aria-label="收起 AI 面板">
          <X size={16} />
        </button>
      </header>

      {shown ? (
        <div className="reader-insight__scroll">
          <div className="reader-insight__term">
            <strong>{shown.text}</strong>
            {shown.kind === "word" ? (
              <button
                type="button"
                aria-label={`朗读 ${shown.text}`}
                onClick={() => speakEnglish(shown.text)}
              >
                <Volume2 size={14} />
              </button>
            ) : null}
          </div>
          {excerpt ? <p className="reader-insight__excerpt">…{excerpt}…</p> : null}

          {loading ? (
            <span className="reader-insight__loading" role="status">
              <LoaderCircle size={15} />
              正在联系 AI…
            </span>
          ) : insight ? (
            <>
              <section className="reader-insight__block">
                <h3>在这里的意思</h3>
                <strong>{insight.meaningsZh.join("；")}</strong>
                <p>{insight.definitionEn}</p>
              </section>
              {insight.usageNotes.length > 0 ? (
                <section className="reader-insight__block">
                  <h3>语境解读</h3>
                  <ul>
                    {insight.usageNotes.map((note) => (
                      <li key={note}>{note}</li>
                    ))}
                  </ul>
                </section>
              ) : null}
              {insight.collocations.length > 0 ? (
                <section className="reader-insight__block">
                  <h3>搭配</h3>
                  <div className="reader-insight__chips">
                    {insight.collocations.slice(0, 5).map((item) => (
                      <span key={item}>{item}</span>
                    ))}
                  </div>
                </section>
              ) : null}
              {insight.examples[0] ? (
                <blockquote className="reader-insight__example">
                  {insight.examples[0].text}
                  {insight.examples[0].translationZh ? (
                    <small>{insight.examples[0].translationZh}</small>
                  ) : null}
                </blockquote>
              ) : null}
            </>
          ) : null}

          <footer>
            <button
              type="button"
              disabled={!insight}
              onClick={() => insight && addToReview(insight, shown.text)}
            >
              <Languages size={14} />
              加入复习
            </button>
            <button
              type="button"
              onClick={() =>
                void saveKnowledgeCard({
                  term: shown.text,
                  contextBefore: shown.contextBefore,
                  contextAfter: shown.contextAfter,
                  insight,
                })
              }
            >
              <BookmarkPlus size={14} />
              存知识卡
            </button>
            <button
              type="button"
              disabled={!insight}
              onClick={() => insight && void addToCorpus(insight)}
            >
              加入语料
            </button>
          </footer>
        </div>
      ) : null}
    </aside>,
    document.body,
  );
}

function contextExcerpt(before: string, text: string, after: string) {
  const lead = before.slice(-46);
  const tail = after.slice(0, 46);
  const body = text.length > 120 ? `${text.slice(0, 120)}…` : text;
  return `${lead}【${body}】${tail}`.trim();
}
